SELECT linked_account_id, SUM(unblended_cost) FROM cur.hourly_view_all GROUP BY 1 ORDER BY 2 DESC;
SELECT DATE_TRUNC('month', usage_date) as month, SUM(unblended_cost) FROM cur.hourly_view_all GROUP BY 1;
SELECT product_code, COUNT(*) FROM cur.hourly_view_all WHERE unblended_cost > 100 GROUP BY product_code;
SELECT product_code, SUM(unblended_cost) FROM cur.hourly_view_all GROUP BY product_code;
SELECT DATE_TRUNC('day', usage_date) as usage_day, SUBSTRING(usage_type, 1, 4) as region, SUM(usage_quantity) as instance_hours FROM cur.hourly_view_all WHERE usage_type LIKE '%BoxUsage%' GROUP BY DATE_TRUNC('day', usage_date), SUBSTRING(usage_type, 1, 4) ORDER BY usage_day DESC, region;
SELECT usage_type, SUM(usage_quantity) as total_usage, SUM(unblended_cost) as total_cost FROM cur.hourly_view_all WHERE usage_type LIKE '%BoxUsage%' AND usage_date >= CURRENT_DATE - INTERVAL '30' DAY GROUP BY usage_type ORDER BY total_cost DESC;
SELECT linked_account_id, charge_type, SUM(unblended_cost) as discount_amount FROM cur.hourly_view_all WHERE charge_type LIKE '%Discount%' AND usage_date >= CURRENT_DATE - INTERVAL '30' DAY GROUP BY linked_account_id, charge_type ORDER BY discount_amount DESC;
SELECT charge_type, COUNT(*) as record_count, SUM(unblended_cost) as total_cost FROM cur.hourly_view_all WHERE usage_date >= CURRENT_DATE - INTERVAL '30' DAY GROUP BY charge_type ORDER BY total_cost DESC;
SELECT usage_date, operation, SUM(usage_quantity) as usage_amount FROM cur.hourly_view_all WHERE operation IN ('RunInstances', 'CreateVolume', 'CreateSnapshot') GROUP BY usage_date, operation ORDER BY usage_date DESC;
SELECT operation, SUM(unblended_cost) as total_cost FROM cur.hourly_view_all WHERE usage_date >= CURRENT_DATE - INTERVAL '30' DAY GROUP BY operation ORDER BY total_cost DESC LIMIT 10;
SELECT region, COUNT(DISTINCT resource_id) as resource_count, SUM(unblended_cost) as total_cost FROM cur.hourly_view_all WHERE usage_date >= CURRENT_DATE - INTERVAL '30' DAY GROUP BY region ORDER BY total_cost DESC;
SELECT resource_id, item_description, SUM(unblended_cost) as total_cost FROM cur.hourly_view_all WHERE resource_id IS NOT NULL AND usage_date >= CURRENT_DATE - INTERVAL '7' DAY GROUP BY resource_id, item_description ORDER BY total_cost DESC LIMIT 10;
SELECT pricing_unit, SUM(usage_quantity) as total_usage, SUM(unblended_cost) as total_cost FROM cur.hourly_view_all WHERE usage_date >= CURRENT_DATE - INTERVAL '30' DAY GROUP BY pricing_unit ORDER BY total_cost DESC;
SELECT region, item_description, SUM(unblended_cost) as cost FROM cur.hourly_view_all WHERE usage_date >= CURRENT_DATE - INTERVAL '30' DAY GROUP BY region, item_description ORDER BY cost DESC LIMIT 10;
SELECT pricing_term, COUNT(*) as usage_count, SUM(unblended_cost) as total_cost FROM cur.hourly_view_all WHERE usage_date >= CURRENT_DATE - INTERVAL '30' DAY GROUP BY pricing_term ORDER BY total_cost DESC;
SELECT DATE_TRUNC('day', usage_date) as usage_day, SUM(unblended_cost) as daily_cost FROM cur.hourly_view_all WHERE usage_date >= CURRENT_DATE - INTERVAL '7' DAY GROUP BY DATE_TRUNC('day', usage_date) ORDER BY usage_day DESC;
SELECT payer_account_id, linked_account_id, SUM(unblended_cost) as total_cost FROM cur.hourly_view_all WHERE usage_date >= CURRENT_DATE - INTERVAL '30' DAY GROUP BY payer_account_id, linked_account_id ORDER BY total_cost DESC;
SELECT linked_account_id, service, SUM(unblended_cost) as service_cost FROM cur.hourly_view_all GROUP BY linked_account_id, service ORDER BY service_cost DESC LIMIT 10;
SELECT savings_plan_a_r_n, SUM(unblended_cost) as total_cost, SUM(savings_plan_effective_cost) as effective_cost, SUM(unblended_cost - savings_plan_effective_cost) as savings FROM cur.hourly_view_all WHERE savings_plan_a_r_n IS NOT NULL GROUP BY savings_plan_a_r_n ORDER BY savings DESC;
SELECT reservation_a_r_n, SUM(unblended_cost) as total_cost, SUM(reservation_effective_cost) as effective_cost, SUM(unblended_cost - reservation_effective_cost) as savings FROM cur.hourly_view_all WHERE reservation_a_r_n IS NOT NULL GROUP BY reservation_a_r_n ORDER BY savings DESC;
SELECT service, SUM(unblended_cost) as on_demand_cost, SUM(reservation_effective_cost) as ri_cost, SUM(savings_plan_effective_cost) as sp_cost FROM cur.hourly_view_all WHERE usage_date >= CAST('2024-07-01' AS TIMESTAMP) AND usage_date < CAST('2024-08-01' AS TIMESTAMP) GROUP BY service ORDER BY on_demand_cost DESC;
SELECT DATE_TRUNC('day', usage_date) as usage_day, SUM(usage_quantity) as total_usage, SUM(unblended_cost) as total_cost FROM cur.hourly_view_all WHERE usage_date >= CURRENT_DATE - INTERVAL '30' DAY GROUP BY DATE_TRUNC('day', usage_date) ORDER BY usage_day;
SELECT instance_type, SUM(usage_quantity) as hours_used, SUM(unblended_cost) as on_demand_cost, SUM(reservation_effective_cost) as ri_cost FROM cur.hourly_view_all WHERE usage_type LIKE '%BoxUsage%' GROUP BY instance_type ORDER BY on_demand_cost DESC LIMIT 10;
SELECT SPLIT_PART(usage_type, ':', 2) as instance_type, SUM(unblended_cost) as total_costFROM cur.hourly_view_allWHERE usage_type LIKE '%BoxUsage%' AND usage_date >= CAST('2024-07-01' AS TIMESTAMP)AND usage_date < CAST('2024-08-01' AS TIMESTAMP) AND service = 'AmazonEC2' GROUP BY SPLIT_PART(usage_type, ':', 2) ORDER BY total_cost DESC LIMIT 5;
SELECT SPLIT_PART(usage_type, ':', 2) as instance_type, pricing_term, SUM(usage_quantity) as total_hours, SUM(unblended_cost) as total_cost FROM cur.hourly_view_all WHERE usage_type LIKE '%BoxUsage%'AND service = 'AmazonEC2'GROUP BY SPLIT_PART(usage_type, ':', 2), pricing_term ORDER BY total_cost DESC;
SELECT region, SPLIT_PART(usage_type, ':', 2) as instance_type, SUM(usage_quantity) as total_hours FROM cur.hourly_view_all WHERE usage_type LIKE '%BoxUsage%'AND service = 'AmazonEC2'AND usage_date >= CURRENT_DATE - INTERVAL '3' MONTHGROUP BY region, SPLIT_PART(usage_type, ':', 2) ORDER BY region, total_hours DESC; 
SELECT SPLIT_PART(usage_type, ':', 2) as instance_type, SUM(unblended_cost)/SUM(usage_quantity) as cost_per_hour FROM cur.hourly_view_all WHERE usage_type LIKE '%BoxUsage%'AND service = 'AmazonEC2'GROUP BY SPLIT_PART(usage_type, ':', 2) ORDER BY cost_per_hour DESC LIMIT 10; 
SELECT resource_id, SPLIT_PART(usage_type, ':', 2) as instance_type, MIN(usage_date) as creation_date, SUM(unblended_cost) as total_cost FROM cur.hourly_view_all WHERE usage_type LIKE '%BoxUsage%'AND service = 'AmazonEC2'AND usage_date >= DATE_TRUNC('month', CURRENT_DATE) GROUP BY resource_id, SPLIT_PART(usage_type, ':', 2) ORDER BY creation_date ASC; 
WITH ranked_instances AS ( SELECT linked_account_id, SPLIT_PART(usage_type, ':', 2) as instance_type, SUM(unblended_cost) as total_cost, ROW_NUMBER() OVER (PARTITION BY linked_account_id ORDER BY SUM(unblended_cost) DESC) as rank FROM cur.hourly_view_all WHERE usage_type LIKE '%BoxUsage%' AND service = 'AmazonEC2' GROUP BY linked_account_id, SPLIT_PART(usage_type, ':', 2) ) SELECT linked_account_id, instance_type, total_cost FROM ranked_instances WHERE rank = 1ORDER BY total_cost DESC; 
WITH ri_usage AS ( SELECT reservation_a_r_n, SPLIT_PART(usage_type, ':', 2) as instance_type, SUM(usage_quantity) as actual_hours, COUNT(DISTINCT DATE_TRUNC('hour', usage_date)) as possible_hours, SUM(reservation_effective_cost) as ri_cost, SUM(unblended_cost) as total_cost FROM cur.hourly_view_all WHERE service = 'AmazonEC2' AND reservation_a_r_n IS NOT NULL AND usage_date >= CAST('2024-07-01' AS TIMESTAMP) AND usage_date < CAST('2024-08-01' AS TIMESTAMP) GROUP BY reservation_a_r_n,service, SPLIT_PART(usage_type, ':', 2) ) SELECT instance_type, reservation_a_r_n, actual_hours, possible_hours, ROUND((actual_hours / possible_hours * 100), 2) as utilization_percentage, ROUND(ri_cost, 2) as ri_cost, ROUND(total_cost, 2) as total_cost FROM ri_usage WHERE (actual_hours / possible_hours * 100) < 70 AND ri_cost > 0 ORDER BY utilization_percentage ASC, ri_cost DESC;
SELECT DATE_TRUNC('month', usage_date) as usage_month, SPLIT_PART(usage_type, ':', 2) as instance_type, SUM(unblended_cost) as total_cost, SUM(savings_plan_effective_cost) as sp_covered_cost, ROUND((SUM(savings_plan_effective_cost) / SUM(unblended_cost) * 100), 2) as sp_coverage_percentage FROM cur.hourly_view_all WHERE service = 'AmazonEC2' AND usage_type LIKE '%BoxUsage%' AND unblended_cost > 0 AND usage_date >= CAST('2024-01-01' AS TIMESTAMP) AND usage_date < CAST('2024-08-01' AS TIMESTAMP) GROUP BY DATE_TRUNC('month', usage_date), SPLIT_PART(usage_type, ':', 2) HAVING (SUM(savings_plan_effective_cost) / SUM(unblended_cost) * 100) < 80 ORDER BY usage_month DESC, sp_coverage_percentage ASC;
SELECT SPLIT_PART(usage_type, ':', 2) as instance_type, SUM(usage_quantity) as usage_hours, SUM(reservation_effective_cost) as ri_cost, ROUND((SUM(usage_quantity) / (744 * COUNT(DISTINCT reservation_a_r_n))) * 100, 2) as utilization_percentage FROM cur.hourly_view_all WHERE service = 'AmazonEC2' AND usage_type LIKE '%BoxUsage%' AND reservation_a_r_n IS NOT NULL GROUP BY SPLIT_PART(usage_type, ':', 2) ORDER BY utilization_percentage DESC;
SELECT DATE_TRUNC('month', usage_date) as usage_month, SUM(unblended_cost) as original_cost, SUM(savings_plan_effective_cost) as sp_cost, ROUND(SUM(unblended_cost - savings_plan_effective_cost), 2) as savings FROM cur.hourly_view_all WHERE service = 'AmazonEC2' AND savings_plan_a_r_n IS NOT NULL GROUP BY DATE_TRUNC('month', usage_date) ORDER BY usage_month DESC;
SELECT SPLIT_PART(usage_type, ':', 2) as instance_type, SUM(usage_quantity) as total_hours, SUM(unblended_cost) as total_cost FROM cur.hourly_view_all WHERE service = 'AmazonEC2' AND reservation_a_r_n IS NULL AND usage_type LIKE '%BoxUsage%' GROUP BY SPLIT_PART(usage_type, ':', 2) ORDER BY total_cost DESC;
SELECT region, SUM(unblended_cost) as total_cost, SUM(savings_plan_effective_cost) as sp_cost, ROUND((SUM(savings_plan_effective_cost) / SUM(unblended_cost) * 100), 2) as coverage_percentage FROM cur.hourly_view_all WHERE service = 'AmazonEC2' GROUP BY region ORDER BY coverage_percentage DESC;
SELECT SPLIT_PART(usage_type, ':', 2) as instance_type, SUM(CASE WHEN reservation_a_r_n IS NOT NULL THEN unblended_cost ELSE 0 END) as ri_cost, SUM(CASE WHEN savings_plan_a_r_n IS NOT NULL THEN unblended_cost ELSE 0 END) as sp_cost FROM cur.hourly_view_all WHERE service = 'AmazonEC2' AND usage_type LIKE '%BoxUsage%' GROUP BY SPLIT_PART(usage_type, ':', 2) ORDER BY ri_cost + sp_cost DESC;
SELECT DATE_TRUNC('day', usage_date) as usage_day, COUNT(DISTINCT reservation_a_r_n) as active_ris, SUM(usage_quantity) as usage_hours, SUM(reservation_effective_cost) as total_cost FROM cur.hourly_view_all WHERE service = 'AmazonEC2' AND reservation_a_r_n IS NOT NULL GROUP BY DATE_TRUNC('day', usage_date) ORDER BY usage_day;
SELECT SPLIT_PART(SPLIT_PART(usage_type, ':', 2), '.', 1) as instance_family, SUM(unblended_cost) as total_cost, SUM(savings_plan_effective_cost) as sp_cost, ROUND((SUM(savings_plan_effective_cost) / NULLIF(SUM(unblended_cost), 0) * 100), 2) as sp_coverage FROM cur.hourly_view_all WHERE service = 'AmazonEC2' AND usage_type LIKE '%BoxUsage%' GROUP BY SPLIT_PART(SPLIT_PART(usage_type, ':', 2), '.', 1) ORDER BY total_cost DESC;
SELECT reservation_a_r_n, SPLIT_PART(usage_type, ':', 2) as instance_type, COUNT(DISTINCT DATE_TRUNC('day', usage_date)) as days_used, SUM(reservation_effective_cost) as total_cost FROM cur.hourly_view_all WHERE service = 'AmazonEC2' AND usage_type LIKE '%BoxUsage%' AND reservation_a_r_n IS NOT NULL GROUP BY reservation_a_r_n, SPLIT_PART(usage_type, ':', 2) ORDER BY days_used DESC;
SELECT linked_account_id, ROUND(SUM(CASE WHEN reservation_effective_cost > 0 THEN 1 ELSE 0 END) * 100.0 / NULLIF(COUNT(*), 0), 2) as ri_percentage, ROUND(SUM(CASE WHEN savings_plan_effective_cost > 0 THEN 1 ELSE 0 END) * 100.0 / NULLIF(COUNT(*), 0), 2) as savings_plan_percentage, ROUND(SUM(CASE WHEN reservation_effective_cost = 0 AND savings_plan_effective_cost = 0 THEN 1 ELSE 0 END) * 100.0 / NULLIF(COUNT(*), 0), 2) as ondemand_percentage, SUM(unblended_cost) as total_cost, SUM(reservation_effective_cost) as ri_cost, SUM(savings_plan_effective_cost) as sp_cost FROM cur.hourly_view_all WHERE service = 'AmazonEC2' AND usage_type LIKE '%BoxUsage%' GROUP BY linked_account_id ORDER BY total_cost DESC;
SELECT DATE_TRUNC('day', usage_date) as usage_day, SUM(CASE WHEN reservation_a_r_n IS NULL AND savings_plan_a_r_n IS NULL THEN unblended_cost ELSE 0 END) as ondemand_cost, SUM(CASE WHEN reservation_a_r_n IS NOT NULL THEN reservation_effective_cost ELSE 0 END) as ri_cost, SUM(CASE WHEN savings_plan_a_r_n IS NOT NULL THEN savings_plan_effective_cost ELSE 0 END) as sp_cost FROM cur.hourly_view_all WHERE service = 'AmazonEC2' GROUP BY DATE_TRUNC('day', usage_date) ORDER BY usage_day;
SELECT linked_account_id, SUM(unblended_cost) as total_cost, SUM(CASE WHEN reservation_a_r_n IS NOT NULL THEN reservation_effective_cost ELSE 0 END) as ri_cost, SUM(CASE WHEN savings_plan_a_r_n IS NOT NULL THEN savings_plan_effective_cost ELSE 0 END) as sp_cost, ROUND(((SUM(CASE WHEN reservation_a_r_n IS NOT NULL THEN reservation_effective_cost ELSE 0 END) + SUM(CASE WHEN savings_plan_a_r_n IS NOT NULL THEN savings_plan_effective_cost ELSE 0 END)) / SUM(unblended_cost) * 100), 2) as coverage_percentage FROM cur.hourly_view_all WHERE service = 'AmazonEC2' GROUP BY linked_account_id ORDER BY total_cost DESC;